#include "obd_can_private.h"
#include <string.h>

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static void vin_append (UInt8 * target , UInt8 * source , UInt8 size) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean obd_can_rx_vin (Obd_Can_Rx_Msg * obd_can_rx_msg)
{
  #define DATA(z) obd_can_rx_msg->data[z]

  #if STATUS_VIN_ENABLE == 1
	  memcpy(&vin[0] , &DATA(2) , VIN_SIZE) ;
	
	  if(vin_validate (vin))
	    {
	      vin_save (vin) ;
	    }
  #endif

#if DBG_OBD_CAN == 1
  dbg_tx_text("*** obd_can_rx_vin = ");
  {
    UInt8 i;
	for (i=0; i<17; i++)
	{
  	  dbg_tx_h8(vin[i]);
	  dbg_tx_text(" ");
	}
  }
  dbg_tx_text("\r\n");
#endif

  return TRUE ;

  #undef DATA
}
